fn prime_num(n: u64) -> bool {
    // By problem statement, n >= 2, but we'll handle smaller edge‐cases defensively.
    if n < 2 {
        return false;
    }
    // 2 is the only even prime
    if n == 2 {
        return true;
    }
    // All other even numbers are composite
    if n % 2 == 0 {
        return false;
    }
    // Only need to test odd divisors up to sqrt(n)
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

